using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ConvertAction", menuName = "Data/Battle/Battle Actions/Moonie/Convert Action")]
public class ConvertAction : ChooseCorruptPurifyDieAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private BattleActionsList battleActionsList;

	[SerializeField]
	private TwilightSigilEffect twilightSigilEffect;

	[SerializeField]
	private bool convertEverything;

	[SerializeField]
	private bool manipulate;

	[SerializeField]
	private bool enableConvertDelay;

	[SerializeField]
	[ShowIf("enableConvertDelay")]
	private float convertDelay;

	public override void Cast(GameObject source)
	{
		if (diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
			{
				DiceInstance diceInstanceFromHand = ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i);
				if (CheckInteraction(diceInstanceFromHand))
				{
					diceList.Add(diceInstanceFromHand);
				}
			}
			if (convertEverything)
			{
				for (int j = 0; j < base.currentCorruptedAnimals.activeCorruptedAnimals.Count; j++)
				{
					CorruptedAnimalActivation component = base.currentCorruptedAnimals.activeCorruptedAnimals[j].GetComponent<CorruptedAnimalActivation>();
					if (!component.BasicDiceSpawned)
					{
						continue;
					}
					DiceInstance basicDiceInstance = component.BasicDiceInstance;
					if (CheckInteraction(basicDiceInstance))
					{
						diceList.Add(basicDiceInstance);
					}
					if (component.IsBoosted)
					{
						DiceInstance boostDiceInstance = component.BoostDiceInstance;
						if (CheckInteraction(boostDiceInstance))
						{
							diceList.Add(boostDiceInstance);
						}
					}
				}
				for (int k = 0; k < base.currentCompanions.ActiveCompanions.Count; k++)
				{
					CompanionAbility component2 = base.currentCompanions.ActiveCompanions[k].GetComponent<CompanionAbility>();
					DiceInstance basicDiceInstance2 = component2.BasicDiceInstance;
					if (CheckInteraction(basicDiceInstance2))
					{
						diceList.Add(basicDiceInstance2);
					}
					if (component2.IsBoosted)
					{
						DiceInstance boostDiceInstance2 = component2.BoostDiceInstance;
						if (CheckInteraction(boostDiceInstance2))
						{
							diceList.Add(boostDiceInstance2);
						}
					}
				}
			}
			DefaultCast(goBackToDiceTray: false);
		}
		else
		{
			DefaultCast(goBackToDiceTray: true);
		}
	}

	private void DefaultCast(bool goBackToDiceTray)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		int diceConvertedAmount = 0;
		for (int i = 0; i < diceList.Count; i++)
		{
			DiceInstance diceInstance = diceList[i];
			bool flag = false;
			bool firstAction = false;
			bool secondAction = false;
			if (diceInstance.ActionFace.BattleAction is CorruptAction)
			{
				flag = true;
				int num = diceConvertedAmount;
				diceConvertedAmount = num + 1;
				firstAction = true;
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is CorruptAction)
			{
				int num = diceConvertedAmount;
				diceConvertedAmount = num + 1;
				flag = true;
				secondAction = true;
			}
			if (!flag)
			{
				continue;
			}
			ConvertFirstSecondAction(diceInstance, firstAction, secondAction);
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AddConvertedDiceAmount(1);
			diceInstance.UpdateActionValueModifier();
			int index = i;
			if (enableConvertDelay)
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, convertDelay, delegate
				{
					SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, index, diceInstance);
				});
			}
			else
			{
				SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, index, diceInstance);
			}
		}
		PlaySFX();
		SpawnSecondVFXOnPlayerPosition(6f);
		if (enableConvertDelay)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, convertDelay, delegate
			{
				EndOfActionActivateEffectsOmensAndReset(goBackToDiceTray, diceConvertedAmount);
			});
		}
		else
		{
			EndOfActionActivateEffectsOmensAndReset(goBackToDiceTray, diceConvertedAmount);
		}
	}

	private void SpawnVFXAndUpdateDiceInstance(bool goBackToDiceTray, int i, DiceInstance diceInstance)
	{
		if (goBackToDiceTray)
		{
			SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance, delegate
			{
				SpawnVFXAndUpdateDiceInstance(diceInstance);
			});
		}
		else
		{
			SpawnVFXAndUpdateDiceInstance(diceInstance);
		}
	}

	private void SpawnVFXAndUpdateDiceInstance(DiceInstance diceInstance)
	{
		if (IsVFXEnabled())
		{
			GameObject vFX = GetVFX(4f);
			vFX.transform.GetFirstChild().gameObject.SetActive(manipulate);
			vFX.GetComponent<ParticleFollower>().Initialize(diceInstance);
		}
		diceInstance.ActionFace.UpdateActionValueModifier();
		diceInstance.UpdateDiceFace();
	}

	private void EndOfActionActivateEffectsOmensAndReset(bool goBackToDiceTray, int diceConvertedAmount)
	{
		EndAction(goBackToDiceTray);
		twilightSigilEffect.Activate(diceConvertedAmount);
		ReferenceSingleton<MoonieOmensHandler>.Instance.ActivateConvertOmens(diceList);
		ResetVariables();
	}

	protected virtual void ConvertFirstSecondAction(DiceInstance diceInstance, bool firstAction, bool secondAction)
	{
		if (firstAction)
		{
			diceInstance.ActionFace.SetActionModifierLock(isLocked: false);
			diceInstance.ActionFace.TurnActionValueIntoModifiedActionValueAndReset();
			diceInstance.ActionFace.BattleAction = GetConvertedBattleAction(diceInstance.ActionFace.BattleAction);
		}
		if (secondAction)
		{
			diceInstance.ActionFace.SetSecondActionModifierLock(isLocked: false);
			diceInstance.ActionFace.TurnSecondActionValueIntoModifiedActionValueAndReset();
			diceInstance.ActionFace.SecondBattleAction = GetConvertedBattleAction(diceInstance.ActionFace.SecondBattleAction);
		}
	}

	public BattleAction GetConvertedBattleAction(BattleAction battleAction)
	{
		string text = "";
		if (!battleAction.name.Contains("CorruptionSource"))
		{
			text = ((!battleAction.name.Contains("Corrupted")) ? battleAction.name.Replace("Corrupt", "Purify") : battleAction.name.Replace("Corrupted", "Purified"));
		}
		else
		{
			text = battleAction.name.Replace("CorruptionSource", "");
			text = text.Replace("Corrupt", "Purify");
			text = "CorruptionSource" + text;
			Debug.Log(text);
		}
		return battleActionsList.GetBattleAction(text);
	}

	public BattleAction GetConvertedBattleActionReverse(BattleAction battleAction)
	{
		string text = "";
		if (!battleAction.name.Contains("CorruptionSource"))
		{
			text = ((!battleAction.name.Contains("Purified")) ? battleAction.name.Replace("Purify", "Corrupt") : battleAction.name.Replace("Purified", "Corrupted"));
		}
		else
		{
			text = battleAction.name.Replace("CorruptionSource", "");
			text = text.Replace("Purify", "Corrupt");
			text = "CorruptionSource" + text;
			Debug.Log(text);
		}
		return battleActionsList.GetBattleAction(text);
	}

	public void ConvertKickOmen()
	{
		DefaultCast(goBackToDiceTray: false);
	}
}
